// Build the HubSpot note (HTML, escaped) and the values for the log row.
// $json holds the Drive file (id wins on merge) and the Gmail result.
const p = $('Build proposal HTML').item.json;
const esc = (v) => String(v ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const pdfLink = $json.id ? `https://drive.google.com/file/d/${$json.id}/view` : '';

const body = [
  `<p><strong>Proposal ${esc(p.proposalNumber)} sent</strong> to ${esc(p.contactName)} (${esc(p.contactEmail)}).</p>`,
  `<p>Investment: ${esc(p.headlineTotal)}<br>Valid until: ${esc(p.validUntil)}</p>`,
  pdfLink ? `<p><a href="${esc(pdfLink)}">Open the PDF in Google Drive</a></p>` : '',
  p.aiUsed ? '' : `<p>The summary is the plain fallback (${esc(p.aiProblem)}).</p>`,
  p.warnings.length ? `<p>Check: ${esc(p.warnings.join('; '))}</p>` : '',
].join('');

return {
  json: {
    ...p,
    html: undefined,
    pdfLink,
    notePayload: {
      properties: { hs_timestamp: new Date().toISOString(), hs_note_body: body },
      associations: [{ to: { id: p.dealId }, types: [{ associationCategory: 'HUBSPOT_DEFINED', associationTypeId: 214 }] }],
    },
  },
};

